package com.eventpulse.service;
import com.eventpulse.model.Event;import com.eventpulse.model.NotificationRecord;import java.util.List;
public class EventLifecycleService {private final NotificationService notifications;private final EventScheduleService schedules;public EventLifecycleService(NotificationService n,EventScheduleService s){notifications=n;schedules=s;}public void created(Event e){announce(e);sync(e);}public List<NotificationRecord> announce(Event e){return notifications.announce(e,NotificationService.EVENT_ANNOUNCEMENT);}public void updated(Event before,Event after){if(!before.getStartDateTime().equals(after.getStartDateTime())||!before.getEndDateTime().equals(after.getEndDateTime()))notifications.announce(after,NotificationService.EVENT_RESCHEDULED);sync(after);}public void cancelled(Event e){notifications.announce(e,NotificationService.EVENT_CANCELLED);try{schedules.cancel(e.getEventId());}catch(RuntimeException ex){throw new ScheduleSyncException(e.getEventId(),ex);}}
 /** Replays the idempotent scheduler projection from the event already persisted in DynamoDB. */
 public void reconcile(Event event){if("CANCELLED".equals(event.getStatus()))schedules.cancel(event.getEventId());else schedules.reschedule(event);}
 private void sync(Event e){try{schedules.reschedule(e);}catch(RuntimeException ex){throw new ScheduleSyncException(e.getEventId(),ex);}}}
